import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;
type CEVariant = 'standard' | 'label_smoothing';

const W = 1400;
const CX = W / 2;
const BOX_H = 100;
const STEP_GAP = 820;
const BOX_TO_ROW = 420;
const FOOTER_PAD = 70;

const C = {
  logits:  { fill: '#e3f2fd', stroke: '#1565c0' },
  softmax: { fill: '#e8f5e9', stroke: '#2e7d32' },
  gather:  { fill: '#fff3e0', stroke: '#e65100' },
  loss:    { fill: '#ffebee', stroke: '#c62828' },
  smooth:  { fill: '#f3e5f5', stroke: '#6a1b9a' },
  header:  { fill: '#e3f2fd', stroke: '#1976d2' },
  muted: 'var(--text-muted)' as string,
};

interface CEStep extends StepInfo {}

function lbl(g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void { drawLabel(g as Sel, x, y, text, opts); }

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = W - 120): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 32).attr('cy', y + BOX_H / 2)
    .attr('r', 18).attr('fill', stroke);
  lbl(g, cx - w / 2 + 32, y + BOX_H / 2 + 1, String(sn), { size: 15, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 62, y + BOX_H / 2 - 10, title, { size: 16, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 62, y + BOX_H / 2 + 14, formula, { size: 11, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(440, text.length * 7.2 + 40);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 15).attr('width', w).attr('height', 30)
    .attr('rx', 4).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1);
  lbl(g, cx, cy + 1, text, { size: 11, color, font: 'monospace' });
}

function sampleNote(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(280, text.length * 6.5 + 32);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 13).attr('width', w).attr('height', 26)
    .attr('rx', 4).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 10, color, font: 'monospace' });
}

function drawBox(g: Gsel, cx: number, cy: number, w: number, h: number,
  label: string, sublabel: string, fill: string, stroke: string): void {
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 2);
  lbl(g, cx, cy - 5, label, { size: 13, weight: '600', color: stroke });
  lbl(g, cx, cy + 13, sublabel, { size: 10, color: C.muted, font: 'monospace' });
}

function makeLCG(seed: number) {
  let s = seed | 0;
  return () => { s = (s * 1664525 + 1013904223) | 0; return ((s >>> 0) / 4294967296); };
}

// Draw a vector as colored cells. cx = CENTER of the entire vector.
function drawVector(g: Gsel, cx: number, cy: number, n: number, cellW: number, cellH: number,
  colors: string[], labelAbove?: string, labelBelow?: string): void {
  const totalW = n * cellW;
  const leftX = cx - totalW / 2;
  if (labelAbove) lbl(g, cx, cy - cellH / 2 - 12, labelAbove, { size: 9, color: C.muted, font: 'monospace' });
  for (let i = 0; i < n; i++) {
    const x = leftX + i * cellW;
    g.append('rect').attr('x', x).attr('y', cy - cellH / 2)
      .attr('width', cellW - 1).attr('height', cellH)
      .attr('rx', 2).attr('fill', colors[i] || '#eee').attr('stroke', '#ccc').attr('stroke-width', 0.5);
  }
  if (labelBelow) lbl(g, cx, cy + cellH / 2 + 14, labelBelow, { size: 9, color: C.muted, font: 'monospace' });
}

// Arrow between two points (horizontal or any direction)
function chainArrow(g: Gsel, x1: number, y: number, x2: number, color: string): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

// Draw chain boxes with arrows between them. Each box has {label, sub, x (center), w}
function drawChain(g: Gsel, cy: number, boxes: { label: string; sub: string; x: number; w: number }[],
  color: string): void {
  for (const box of boxes) {
    g.append('rect').attr('x', box.x - box.w / 2).attr('y', cy - 30).attr('width', box.w).attr('height', 60)
      .attr('rx', 6).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
    lbl(g, box.x, cy - 9, box.label, { size: 10, color, font: 'monospace' });
    lbl(g, box.x, cy + 13, box.sub, { size: 12, weight: '600', color, font: 'monospace' });
  }
  for (let i = 0; i < boxes.length - 1; i++) {
    const x1 = boxes[i].x + boxes[i].w / 2;
    const x2 = boxes[i + 1].x - boxes[i + 1].w / 2;
    chainArrow(g, x1 + 4, cy, x2 - 4, color);
  }
}

// Vertical arrow between elements
function vArrow(g: Gsel, x: number, y1: number, y2: number, color: string): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

// ── Shared helpers ────────────────────────────────────────────────────

function makeStep(id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]): CEStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

// ── Standard variant renderer ────────────────────────────────────────

function renderStandard(g: Gsel, startY: number, B: number, V: number): { steps: CEStep[]; y: number } {
  const steps: CEStep[] = [];
  let y = startY;

  const showB = Math.min(B, 4);
  const showV = Math.min(V, 8);
  const rng = makeLCG(42);
  const logits: number[][] = Array.from({ length: showB }, () =>
    Array.from({ length: showV }, () => (rng() * 4 - 2))
  );
  const row0 = logits[0];
  const maxVal = Math.max(...row0);
  const exps = row0.map((v) => Math.exp(v - maxVal));
  const sumExp = exps.reduce((a, b) => a + b, 0);
  const softRow0 = exps.map((e) => e / sumExp);
  const logSoftRow0 = softRow0.map((p) => Math.log(p));
  const targetIdx = 2;
  const nll0 = -logSoftRow0[targetIdx];

  // ── Step 1: Input Logits & Targets ─────────────────────────────────
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-inputs', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input: Logits & Target Classes',
      `logits: [${B} × ${V}],  targets: [${B}]`,
      C.header.fill, C.header.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Logits matrix (left) — drawMatrixBlock uses top-left corner
    const matW = 200, matH = 140;
    const matLeftX = CX - 340;
    const matRightX = matLeftX + matW;
    drawMatrixBlock(gs as Sel, matLeftX, rowY - matH / 2, {
      width: matW, height: matH, label: 'logits', sublabel: `[${B} × ${V}]`,
      fill: C.logits.fill, stroke: C.logits.stroke,
      dimLeft: `B = ${B}`, dimTop: `V = ${V}`,
    });
    lbl(gs, matLeftX + matW / 2, rowY + matH / 2 + 18, 'raw class scores (unnormalized)',
      { size: 9, color: C.muted, font: 'monospace' });

    // Targets box (right) — drawBox uses center
    const targCX = CX + 220;
    const targW = 180;
    drawBox(gs, targCX, rowY - 20, targW, 70, 'targets', `[${B}] — class indices`, C.gather.fill, C.gather.stroke);
    lbl(gs, targCX, rowY + 10, `e.g. [${targetIdx}, 5, 1, 3, ...]`, { size: 9, color: C.muted, font: 'monospace' });

    // Horizontal arrow from matrix right edge to targets left edge
    const arrowY = rowY - 20;
    drawArrow(gs as Sel, matRightX + 12, arrowY, targCX - targW / 2 - 8, arrowY, { color: C.header.stroke });

    // Formula note
    shapeEq(gs, CX, rowY + 100,
      `logits[i,j] = unnormalized score for sample i, class j`,
      C.header.stroke);
    sampleNote(gs, CX, rowY + 100 + 38,
      `targets[i] = ground-truth class index for sample i (integer)`, C.header.stroke);

    y = rowY + 100 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Inputs', 'Input: Logits & Targets',
      `logits[${B}, ${V}], targets[${B}]`,
      `The input logits are unnormalized scores (raw model output) of shape [batch, vocab]. The targets are integer class indices indicating the correct class for each sample. Cross-entropy computes how well the predicted distribution matches the ground truth.`,
      'step-inputs', C.header.stroke, C.header.fill,
      [`# logits: [B, V] — raw model output`, `# targets: [B]  — integer class indices`, `logits = model(x)  # shape [${B}, ${V}]`, `targets = torch.tensor([${targetIdx}, 5, 1, 3, ...])  # shape [${B}]`]));
  }

  // ── Step 2: Log-Softmax ───────────────────────────────────────────
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-logsoftmax', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Log-Softmax',
      `log_p = log(softmax(logits, dim=-1))`,
      C.softmax.fill, C.softmax.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Computation chain — 6 boxes, centered around CX
    // Total span: ~1000px, from CX-500 to CX+500
    const chainY = rowY;
    const z0 = row0[0];
    const z0shifted = z0 - maxVal;
    const boxes = [
      { label: 'z_i', sub: z0.toFixed(3), x: CX - 480, w: 120 },
      { label: 'z_i − max(z)', sub: z0shifted.toFixed(3), x: CX - 320, w: 140 },
      { label: 'exp(·)', sub: exps[0].toFixed(4), x: CX - 160, w: 120 },
      { label: 'p_i = ÷ Σexp', sub: softRow0[0].toFixed(4), x: CX + 20, w: 150 },
      { label: 'log(p_i)', sub: logSoftRow0[0].toFixed(4), x: CX + 200, w: 130 },
      { label: 'log_p[i,·]', sub: `[${V}] values`, x: CX + 390, w: 130 },
    ];
    drawChain(gs, chainY, boxes, C.softmax.stroke);

    // Numerical stability note
    lbl(gs, CX, chainY + 50,
      `numerical stability: subtract max(z) before exp — doesn't change softmax result`,
      { size: 9, color: C.muted, font: 'monospace' });

    // Show first row softmax probabilities as colored cells
    const cellW = 48, cellH = 36;
    const probCX = CX;
    const probY = chainY + 110;
    const probColors = softRow0.map((p) => d3.interpolate('#fff', C.softmax.stroke)(0.15 + p * 0.7));
    drawVector(gs, probCX, probY, showV, cellW, cellH, probColors,
      `softmax output for sample 0: [${showV} class probabilities]`,
      `softmax(z)[j] ∈ (0,1),  Σ p_j = 1`);

    // Vertical arrow from chain to softmax vector
    vArrow(gs, CX, chainY + 30, probY - cellH / 2 - 12, C.softmax.stroke);

    // Show log_softmax output
    const logY = probY + 90;
    const logColors = logSoftRow0.map((lp) => d3.interpolate('#fff', C.softmax.stroke)(0.15 + Math.min(1, (-lp) / 8) * 0.7));
    drawVector(gs, probCX, logY, showV, cellW, cellH, logColors,
      `log_softmax output for sample 0: [all ≤ 0]`,
      `log_p[j] = log(p[j]) ≤ 0  (more negative = lower probability)`);

    // Vertical arrow from softmax to log
    vArrow(gs, CX, probY + cellH / 2 + 14, logY - cellH / 2 - 12, C.softmax.stroke);

    shapeEq(gs, CX, logY + 60,
      `log_p = F.log_softmax(logits, dim=-1)   shape: [${B}, ${V}]`,
      C.softmax.stroke);
    sampleNote(gs, CX, logY + 60 + 38,
      `all log-probabilities are ≤ 0  (log(1) = 0,  log(→0) → −∞)`, C.softmax.stroke);

    y = logY + 60 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Log-Softmax', 'Log-Softmax',
      `log_p = log(softmax(logits))`,
      `Log-softmax converts raw logits to log-probabilities. Numerically stable: log_p[j] = z[j] − max(z) − log(Σ exp(z[k] − max(z))). The result is a [B×V] matrix of log-probabilities, all ≤ 0, summing (in exp) to 1 per row.`,
      'step-logsoftmax', C.softmax.stroke, C.softmax.fill,
      [`log_p = F.log_softmax(logits, dim=-1)`, `# shape: [${B}, ${V}]`, `# each log_p[i,:] sums to log(1)=0 in exp space`, `# log_p[i,j] = z[i,j] - log(sum_k exp(z[i,k]))`]));
  }

  // ── Step 3: Gather target log-probabilities ───────────────────────
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-gather', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Gather Target Log-Probabilities',
      `nll[i] = −log_p[i, targets[i]]`,
      C.gather.fill, C.gather.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // log_p matrix (left)
    const matW = 200, matH = 140;
    const matLeftX = CX - 340;
    const matRightX = matLeftX + matW;
    drawMatrixBlock(gs as Sel, matLeftX, rowY - matH / 2, {
      width: matW, height: matH, label: 'log_p', sublabel: `[${B} × ${V}]`,
      fill: C.softmax.fill, stroke: C.softmax.stroke,
      dimLeft: `B = ${B}`, dimTop: `V = ${V}`,
    });

    // Highlight the gathered cell (row 0, col targetIdx)
    const cellH2 = matH / Math.min(showB, 4);
    const cellW2 = matW / Math.min(showV, 8);
    gs.append('rect')
      .attr('x', matLeftX + targetIdx * cellW2)
      .attr('y', rowY - matH / 2 + 0 * cellH2)
      .attr('width', cellW2).attr('height', cellH2)
      .attr('fill', C.gather.stroke).attr('opacity', 0.35).attr('rx', 1);
    lbl(gs, matLeftX + targetIdx * cellW2 + cellW2 / 2,
      rowY - matH / 2 + 0 * cellH2 + cellH2 / 2, '★', { size: 8, color: '#fff' });
    lbl(gs, matLeftX + matW / 2, rowY + matH / 2 + 18,
      `gather log_p[i, target_i]  for each row i`, { size: 9, color: C.muted, font: 'monospace' });

    // Gathered vector (right) — centered at gathCX
    const gathCX = CX + 200;
    const gathCellW = 60, gathCellH = 38;
    const gathTotalW = showB * gathCellW;
    const gathLeftX = gathCX - gathTotalW / 2;

    // Arrow from matrix right edge to gathered vector left edge
    drawArrow(gs as Sel, matRightX + 12, rowY, gathLeftX - 10, rowY, { color: C.gather.stroke });

    const gathColors = Array.from({ length: showB }, (_, i) =>
      d3.interpolate('#fff', C.gather.stroke)(0.2 + (i === 0 ? 0.6 : 0.3)));
    drawVector(gs, gathCX, rowY, showB, gathCellW, gathCellH, gathColors,
      `gathered: [${showB}] — nll per sample`,
      `−log_p[0,${targetIdx}] = ${nll0.toFixed(4)}`);

    // Computation chain below
    const chainY = rowY + 120;
    const chainBoxes = [
      { label: 'log_p[i, target_i]', sub: logSoftRow0[targetIdx].toFixed(4), x: CX - 220, w: 180 },
      { label: '× (−1)', sub: `nll_i = ${nll0.toFixed(4)}`, x: CX + 80, w: 150 },
    ];
    drawChain(gs, chainY, chainBoxes, C.gather.stroke);

    // Vertical arrow from gathered vector to chain
    vArrow(gs, gathCX, rowY + gathCellH / 2 + 14, chainY - 30, C.gather.stroke);

    shapeEq(gs, CX, chainY + 60,
      `nll = -log_p.gather(dim=-1, index=targets.unsqueeze(-1))   shape: [${B}]`,
      C.gather.stroke);
    sampleNote(gs, CX, chainY + 60 + 38,
      `negative log-likelihood: higher loss = model was less confident in correct class`, C.gather.stroke);

    y = chainY + 60 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Gather', 'Gather Target Log-Probs',
      `nll[i] = −log_p[i, targets[i]]`,
      `For each sample i, we select the log-probability corresponding to the true target class. This is the gather operation: nll[i] = −log_p[i, targets[i]]. A confident correct prediction gives log_p[target] ≈ 0 (→ small loss); a wrong/uncertain prediction gives very negative log_p (→ large loss).`,
      'step-gather', C.gather.stroke, C.gather.fill,
      [`# Gather log-probs at target positions`, `nll = -log_p.gather(dim=-1, targets.unsqueeze(-1))`, `# shape: [${B}, 1] → squeeze to [${B}]`, `nll = nll.squeeze(-1)  # shape [${B}]`]));
  }

  // ── Step 4: Mean reduction → scalar loss ──────────────────────────
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-mean', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Mean Reduction → Scalar Loss',
      `L = mean(nll) = (1/${B}) Σ −log_p[i, target_i]`,
      C.loss.fill, C.loss.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // nll vector (left)
    const nllCellW = 60, nllCellH = 38;
    const nllCX = CX - 240;
    const nllTotalW = showB * nllCellW;
    const nllRightX = nllCX + nllTotalW / 2;
    const nllColors = Array.from({ length: showB }, () =>
      d3.interpolate('#fff', C.loss.stroke)(0.3 + rng() * 0.5));
    drawVector(gs, nllCX, rowY - 30, showB, nllCellW, nllCellH, nllColors,
      `nll: [${B}] — per-sample loss`,
      `nll[0]=${nll0.toFixed(4)}, ...`);

    // Arrow from nll vector right edge to mean box left edge
    const meanCX = CX + 140;
    const meanW = 140;
    drawArrow(gs as Sel, nllRightX + 12, rowY - 30, meanCX - meanW / 2 - 8, rowY - 30, { color: C.loss.stroke });

    // mean box
    gs.append('rect').attr('x', meanCX - meanW / 2).attr('y', rowY - 80).attr('width', meanW).attr('height', 100)
      .attr('rx', 8).attr('fill', C.loss.fill).attr('stroke', C.loss.stroke).attr('stroke-width', 2);
    lbl(gs, meanCX, rowY - 50, 'mean(·)', { size: 12, weight: '600', color: C.loss.stroke });
    lbl(gs, meanCX, rowY - 28, `(1/${B}) Σ nll_i`, { size: 10, color: C.loss.stroke, font: 'monospace' });

    // Arrow from mean box to loss circle
    const lossCX = CX + 360;
    const lossR = 44;
    drawArrow(gs as Sel, meanCX + meanW / 2 + 8, rowY - 30, lossCX - lossR - 6, rowY - 30, { color: C.loss.stroke });
    gs.append('circle').attr('cx', lossCX).attr('cy', rowY - 30).attr('r', lossR)
      .attr('fill', C.loss.fill).attr('stroke', C.loss.stroke).attr('stroke-width', 2.5);
    lbl(gs, lossCX, rowY - 40, 'L', { size: 16, weight: '700', color: C.loss.stroke });
    lbl(gs, lossCX, rowY - 18, 'scalar', { size: 10, color: C.muted, font: 'monospace' });

    // Full formula breakdown chain below
    const chainY = rowY + 80;
    const chainBoxes = [
      { label: 'nll_i', sub: `[${B}] values`, x: CX - 360, w: 140 },
      { label: 'Σ nll_i', sub: `sum`, x: CX - 160, w: 120 },
      { label: `÷ ${B}`, sub: `mean`, x: CX + 20, w: 100 },
      { label: 'L', sub: `scalar`, x: CX + 180, w: 100 },
    ];
    drawChain(gs, chainY, chainBoxes, C.loss.stroke);

    shapeEq(gs, CX, chainY + 60,
      `L = F.cross_entropy(logits, targets)  =  mean(−log_softmax(logits)[arange(B), targets])`,
      C.loss.stroke);
    sampleNote(gs, CX, chainY + 60 + 38,
      `scalar loss — differentiable, used for backpropagation to update all model parameters`, C.loss.stroke);

    y = chainY + 60 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Mean Loss', 'Mean Reduction → Scalar Loss',
      `L = mean(−log p[target])`,
      `The mean operation reduces the per-sample NLL vector to a scalar. L = (1/B) Σᵢ −log_softmax(logits[i])[targets[i]]. This scalar is the loss that will be backpropagated to update all model parameters.`,
      'step-mean', C.loss.stroke, C.loss.fill,
      [`loss = nll.mean()`, `# OR equivalently:`, `loss = F.cross_entropy(logits, targets)`, `# F.cross_entropy combines log_softmax + nll_loss`, `# loss is a scalar — backprop flows through this`]));
  }

  // ── Step 5: Loss Landscape — what makes good predictions ──────────
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-landscape', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Loss Landscape & Gradient Signal',
      `L = −log(p_target)  →  low when confident & correct`,
      C.header.fill, C.header.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Draw −log(p) curve
    const curveW = 500, curveH = 160;
    const curveCX = CX;
    const curveLeftX = curveCX - curveW / 2;
    const curveY = rowY;
    const nPts = 60;
    const pts: [number, number][] = [];
    for (let i = 0; i <= nPts; i++) {
      const p = 0.005 + (i / nPts) * 0.99;
      const lossVal = -Math.log(p);
      const px = curveLeftX + (i / nPts) * curveW;
      const py = curveY + curveH - Math.min(lossVal / 6, 1) * curveH;
      pts.push([px, py]);
    }
    // Axes
    gs.append('line').attr('x1', curveLeftX).attr('y1', curveY + curveH)
      .attr('x2', curveLeftX + curveW).attr('y2', curveY + curveH)
      .attr('stroke', '#ccc').attr('stroke-width', 1);
    gs.append('line').attr('x1', curveLeftX).attr('y1', curveY)
      .attr('x2', curveLeftX).attr('y2', curveY + curveH + 10)
      .attr('stroke', '#ccc').attr('stroke-width', 1);
    lbl(gs, curveCX, curveY + curveH + 22, `p_target (predicted probability of correct class)`,
      { size: 9, color: C.muted, font: 'monospace' });
    lbl(gs, curveLeftX - 40, curveY + curveH / 2, `−log(p)`,
      { size: 9, color: C.muted, font: 'monospace', anchor: 'middle' });

    const lineGen = d3.line<[number, number]>().x((d) => d[0]).y((d) => d[1]);
    gs.append('path').attr('d', lineGen(pts) || '')
      .attr('fill', 'none').attr('stroke', C.loss.stroke).attr('stroke-width', 2.5);

    // Annotate key points on curve
    const p9 = 0.9, lv9 = -Math.log(p9);
    const x9 = curveLeftX + p9 * curveW;
    const y9 = curveY + curveH - Math.min(lv9 / 6, 1) * curveH;
    gs.append('circle').attr('cx', x9).attr('cy', y9).attr('r', 5).attr('fill', C.softmax.stroke);
    lbl(gs, x9 + 10, y9 - 10, `p=0.9 → loss=${lv9.toFixed(3)}`, { size: 9, color: C.softmax.stroke, font: 'monospace', anchor: 'start' });

    const p1 = 0.1, lv1 = -Math.log(p1);
    const x1 = curveLeftX + p1 * curveW;
    const y1 = curveY + curveH - Math.min(lv1 / 6, 1) * curveH;
    gs.append('circle').attr('cx', x1).attr('cy', y1).attr('r', 5).attr('fill', C.loss.stroke);
    lbl(gs, x1 + 10, y1 - 10, `p=0.1 → loss=${lv1.toFixed(3)}`, { size: 9, color: C.loss.stroke, font: 'monospace', anchor: 'start' });

    // Gradient signal: 3 cases, ordered left→right as p increases
    const gradY = rowY + curveH + 90;
    const cases = [
      { p: 0.05, label: 'p=0.05 → gradient large', color: C.loss.stroke },
      { p: 0.50, label: 'p=0.50 → gradient medium', color: C.gather.stroke },
      { p: 0.95, label: 'p=0.95 → gradient small', color: C.softmax.stroke },
    ];
    const caseCols = [CX - 280, CX, CX + 280];
    for (let i = 0; i < cases.length; i++) {
      const cas = cases[i];
      const cx2 = caseCols[i];
      const grad = cas.p - 1;
      const barH = Math.abs(grad) * 80;
      gs.append('rect').attr('x', cx2 - 30).attr('y', gradY - barH).attr('width', 60).attr('height', barH)
        .attr('fill', cas.color).attr('opacity', 0.45).attr('rx', 3);
      lbl(gs, cx2, gradY + 16, cas.label, { size: 9, color: cas.color, font: 'monospace' });
      lbl(gs, cx2, gradY - barH - 10, `∂L/∂z = ${grad.toFixed(2)}`, { size: 9, color: cas.color, weight: '600', font: 'monospace' });
    }

    shapeEq(gs, CX, gradY + 50,
      `∂L/∂z_j = p_j − y_j    where y_j = 1 if j=target, 0 otherwise`,
      C.header.stroke);
    sampleNote(gs, CX, gradY + 50 + 38,
      `gradient pushes logit for correct class up, all others down`, C.header.stroke);

    y = gradY + 50 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Loss Landscape', 'Loss Landscape & Gradients',
      `∂L/∂z_j = p_j − 1[j=target]`,
      `The cross-entropy loss −log(p_target) is convex in p. When the model is confident and correct (p≈1), the loss is near 0 and the gradient is small. When uncertain or wrong (p≈0), the loss is large and the gradient pushes the logits to favor the correct class.`,
      'step-landscape', C.header.stroke, C.header.fill,
      [`# Gradient w.r.t. logits (softmax + CE combined)`, `# ∂L/∂z_j = p_j - 1[j == target_class]`, `# This is extremely elegant: subtract 1 at target position`, `# Example: target=2, p=[0.1, 0.1, 0.7, 0.1]`, `# grad = [0.1, 0.1, -0.3, 0.1]`]));
  }

  return { steps, y };
}

// ── Label-Smoothing variant renderer ────────────────────────────────

function renderLabelSmoothing(g: Gsel, startY: number, B: number, V: number): { steps: CEStep[]; y: number } {
  const steps: CEStep[] = [];
  let y = startY;
  const eps = 0.1;
  const smoothed0 = eps / V;
  const smoothed_target = 1 - eps + eps / V;

  // ── Step 1: Input Logits & Hard Targets ───────────────────────────
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-inputs', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input: Logits & Hard Targets',
      `logits: [${B} × ${V}],  targets: [${B}]  (integer)`,
      C.header.fill, C.header.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const matW = 200, matH = 130;
    const matLeftX = CX - 340;
    const matRightX = matLeftX + matW;
    drawMatrixBlock(gs as Sel, matLeftX, rowY - matH / 2, {
      width: matW, height: matH, label: 'logits', sublabel: `[${B} × ${V}]`,
      fill: C.logits.fill, stroke: C.logits.stroke,
      dimLeft: `B = ${B}`, dimTop: `V = ${V}`,
    });

    const targCX = CX + 220;
    const targW = 180;
    drawBox(gs, targCX, rowY - 20, targW, 60, 'targets', `[${B}] — hard labels`, C.gather.fill, C.gather.stroke);
    drawArrow(gs as Sel, matRightX + 12, rowY - 10, targCX - targW / 2 - 8, rowY - 10, { color: C.header.stroke });

    shapeEq(gs, CX, rowY + 80, `hard one-hot targets: y[target] = 1, y[j≠target] = 0`, C.header.stroke);
    sampleNote(gs, CX, rowY + 80 + 38, `problem: hard labels → overconfident predictions, poor generalization`, C.header.stroke);

    y = rowY + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Inputs', 'Input: Logits & Hard Targets',
      `logits[${B}, ${V}], targets[${B}]`,
      `Label smoothing addresses the overconfidence problem of hard one-hot targets. Hard labels push the model to assign probability 1.0 to the target class, which can cause overfitting and poor calibration.`,
      'step-inputs', C.header.stroke, C.header.fill,
      [`logits = model(x)  # shape [${B}, ${V}]`, `targets = torch.tensor([2, 5, 1, ...])  # hard indices`]));
  }

  // ── Step 2: Label Smoothing — convert hard → soft targets ─────────
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-smooth', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Label Smoothing: Hard → Soft Targets',
      `y_smooth = (1−ε)·one_hot + ε/V    [ε = ${eps}]`,
      C.smooth.fill, C.smooth.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Hard one-hot vector (left)
    const showV2 = Math.min(V, 8);
    const cellW5 = 44, cellH5 = 36;
    const hardTotalW = showV2 * cellW5;
    const hardCX = CX - 280;
    const hardRightX = hardCX + hardTotalW / 2;
    const hotTarget = 2;
    const hardColors = Array.from({ length: showV2 }, (_, i) =>
      i === hotTarget ? C.gather.stroke : '#eee');
    drawVector(gs, hardCX, rowY - 60, showV2, cellW5, cellH5, hardColors,
      `one_hot(target) — hard label`,
      `[0, 0, 1, 0, 0, 0, 0, 0]`);

    // Formula between vectors
    lbl(gs, CX - 50, rowY + 5, `× (1 − ${eps})`, { size: 11, color: C.smooth.stroke, font: 'monospace', weight: '600' });
    lbl(gs, CX - 50, rowY + 25, `+ ${eps} / ${V} = ${(eps / V).toFixed(4)}`, { size: 11, color: C.smooth.stroke, font: 'monospace' });

    // Soft target vector (right)
    const softCX = CX + 280;
    const softTotalW = showV2 * cellW5;
    const softLeftX = softCX - softTotalW / 2;
    const softColors = Array.from({ length: showV2 }, (_, i) =>
      d3.interpolate('#fff', C.smooth.stroke)(i === hotTarget ? smoothed_target : smoothed0 * 4));
    drawVector(gs, softCX, rowY - 20, showV2, cellW5, cellH5, softColors,
      `y_smooth — soft label`,
      `[${smoothed0.toFixed(3)}, .., ${smoothed_target.toFixed(3)}, .., ${smoothed0.toFixed(3)}]`);

    // Arrow from hard vector right edge to soft vector left edge
    drawArrow(gs as Sel, hardRightX + 12, rowY - 40, softLeftX - 10, rowY - 20, { color: C.smooth.stroke });

    // Chain showing the formula
    const chainY = rowY + 100;
    const chainBoxes = [
      { label: 'one_hot[target]=1', sub: `hard`, x: CX - 360, w: 160 },
      { label: `× (1−${eps})`, sub: `${1 - eps}`, x: CX - 140, w: 120 },
      { label: `+ ε/V`, sub: `${smoothed0.toFixed(4)}`, x: CX + 40, w: 130 },
      { label: 'y_smooth[j]', sub: smoothed_target.toFixed(4), x: CX + 240, w: 140 },
    ];
    drawChain(gs, chainY, chainBoxes, C.smooth.stroke);

    shapeEq(gs, CX, chainY + 60,
      `y_smooth = (1−${eps}) × one_hot(t) + ${eps}/${V}    for each class j`,
      C.smooth.stroke);
    sampleNote(gs, CX, chainY + 60 + 38,
      `non-target classes get small probability ${smoothed0.toFixed(4)} instead of 0`, C.smooth.stroke);

    y = chainY + 60 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Smoothing', 'Label Smoothing Transform',
      `y_smooth = (1−ε)·one_hot + ε/V`,
      `Label smoothing replaces the hard one-hot vector with a soft distribution. The target class gets probability (1−ε)+ε/V ≈ 0.91 instead of 1.0. All other classes get ε/V ≈ 0.0125 instead of 0. This prevents overconfident predictions and improves calibration.`,
      'step-smooth', C.smooth.stroke, C.smooth.fill,
      [`eps = 0.1`, `# one_hot: [0, 0, 1, 0, ..., 0]  shape [V]`, `y_smooth = (1 - eps) * one_hot + eps / V`, `# target:     ${smoothed_target.toFixed(4)} = (1-0.1) + 0.1/${V}`, `# non-target: ${smoothed0.toFixed(4)} = 0.1/${V}`]));
  }

  // ── Step 3: Log-Softmax on logits ─────────────────────────────────
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-logsoftmax', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Log-Softmax on Logits',
      `log_p = log_softmax(logits, dim=-1)   shape: [${B}, ${V}]`,
      C.softmax.fill, C.softmax.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const chainBoxes = [
      { label: 'logits[i,·]', sub: `[${V}]`, x: CX - 380, w: 130 },
      { label: '− max(z)', sub: `stable`, x: CX - 200, w: 120 },
      { label: 'exp(·)', sub: `≥ 0`, x: CX - 40, w: 110 },
      { label: '÷ Σexp', sub: `prob`, x: CX + 120, w: 120 },
      { label: 'log(p)', sub: `log_p[i,·]`, x: CX + 310, w: 140 },
    ];
    drawChain(gs, rowY, chainBoxes, C.softmax.stroke);

    // Matrix below
    const matW = 220, matH = 120;
    drawMatrixBlock(gs as Sel, CX - matW / 2, rowY + 80, {
      width: matW, height: matH, label: 'log_p', sublabel: `[${B} × ${V}]`,
      fill: C.softmax.fill, stroke: C.softmax.stroke,
      dimLeft: `B`, dimTop: `V`,
    });

    // Vertical arrow from chain to matrix
    vArrow(gs, CX, rowY + 30, rowY + 80 - 8, C.softmax.stroke);

    shapeEq(gs, CX, rowY + 230,
      `log_p = F.log_softmax(logits, dim=-1)   shape: [${B}, ${V}]`,
      C.softmax.stroke);
    sampleNote(gs, CX, rowY + 230 + 38,
      `same as standard CE — log_softmax converts logits to log-probabilities`, C.softmax.stroke);

    y = rowY + 230 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Log-Softmax', 'Log-Softmax on Logits',
      `log_p = log_softmax(logits, dim=-1)`,
      `Identical to standard cross-entropy: compute log-probabilities via numerically stable log-softmax. The difference from standard CE comes in the next step where we use the soft targets instead of gathering a single index.`,
      'step-logsoftmax', C.softmax.stroke, C.softmax.fill,
      [`log_p = F.log_softmax(logits, dim=-1)`, `# shape: [${B}, ${V}]`]));
  }

  // ── Step 4: Dot product with soft targets ─────────────────────────
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-dotprod', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Soft Cross-Entropy: −Σ y_smooth · log_p',
      `L_i = −Σ_j  y_smooth[j] · log_p[i,j]`,
      C.gather.fill, C.gather.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Show y_smooth and log_p vectors being multiplied element-wise
    const showV3 = Math.min(V, 8);
    const cW = 44, cH = 34;
    const vecTotalW = showV3 * cW;
    const vecCX = CX - 200;
    const vecRightX = vecCX + vecTotalW / 2;

    const smoothColors2 = Array.from({ length: showV3 }, (_, i) =>
      d3.interpolate('#fff', C.smooth.stroke)(i === 2 ? 0.8 : 0.2));
    const logPColors = Array.from({ length: showV3 }, () =>
      d3.interpolate('#fff', C.softmax.stroke)(0.3 + makeLCG(99)() * 0.4));

    drawVector(gs, vecCX, rowY - 70, showV3, cW, cH, smoothColors2,
      `y_smooth[j]  (soft targets)`,
      `[${smoothed0.toFixed(3)}, ${smoothed0.toFixed(3)}, ${smoothed_target.toFixed(3)}, ...]`);

    // ⊙ symbol between vectors
    lbl(gs, vecCX, rowY - 20, '⊙  (element-wise multiply)', { size: 11, color: C.gather.stroke, weight: '600' });

    drawVector(gs, vecCX, rowY + 30, showV3, cW, cH, logPColors,
      `log_p[i,j]  (log-probabilities)`, `[all ≤ 0]`);

    // Arrow from log_p vector right edge to sum box left edge
    const sumCX = CX + 200;
    const sumW = 120;
    drawArrow(gs as Sel, vecRightX + 12, rowY + 30, sumCX - sumW / 2 - 8, rowY + 30, { color: C.gather.stroke });

    gs.append('rect').attr('x', sumCX - sumW / 2).attr('y', rowY - 20).attr('width', sumW).attr('height', 100)
      .attr('rx', 6).attr('fill', C.gather.fill).attr('stroke', C.gather.stroke).attr('stroke-width', 2);
    lbl(gs, sumCX, rowY + 20, '−Σ(·)', { size: 14, weight: '600', color: C.gather.stroke });
    lbl(gs, sumCX, rowY + 42, 'sum + negate', { size: 9, color: C.muted, font: 'monospace' });

    // Arrow from sum box to loss circle
    const lossCX = CX + 380;
    const lossR = 44;
    drawArrow(gs as Sel, sumCX + sumW / 2 + 8, rowY + 30, lossCX - lossR - 6, rowY + 30, { color: C.gather.stroke });
    gs.append('circle').attr('cx', lossCX).attr('cy', rowY + 30).attr('r', lossR)
      .attr('fill', C.loss.fill).attr('stroke', C.loss.stroke).attr('stroke-width', 2.5);
    lbl(gs, lossCX, rowY + 20, 'L_i', { size: 14, weight: '700', color: C.loss.stroke });
    lbl(gs, lossCX, rowY + 40, 'per-sample', { size: 9, color: C.muted, font: 'monospace' });

    // Compare standard vs smooth
    const compY = rowY + 130;
    const compW = 400;
    const compH = 70;
    gs.append('rect').attr('x', CX - compW - 20).attr('y', compY).attr('width', compW).attr('height', compH)
      .attr('rx', 6).attr('fill', C.logits.fill).attr('stroke', C.logits.stroke).attr('stroke-width', 1.5);
    lbl(gs, CX - compW - 20 + 20, compY + 18, 'Standard CE:', { size: 11, weight: '600', color: C.logits.stroke, anchor: 'start' });
    lbl(gs, CX - compW - 20 + 20, compY + 40, `L_i = −log_p[i, target_i]  (single term)`, { size: 10, color: C.logits.stroke, font: 'monospace', anchor: 'start' });

    gs.append('rect').attr('x', CX + 20).attr('y', compY).attr('width', compW).attr('height', compH)
      .attr('rx', 6).attr('fill', C.smooth.fill).attr('stroke', C.smooth.stroke).attr('stroke-width', 1.5);
    lbl(gs, CX + 40, compY + 18, 'Label Smooth CE:', { size: 11, weight: '600', color: C.smooth.stroke, anchor: 'start' });
    lbl(gs, CX + 40, compY + 40, `L_i = −Σ_j y_smooth[j]·log_p[j]  (V terms)`, { size: 10, color: C.smooth.stroke, font: 'monospace', anchor: 'start' });

    shapeEq(gs, CX, compY + 110,
      `L = mean(L_i)   scalar  —  label smoothing adds small penalty for overconfidence`,
      C.gather.stroke);
    sampleNote(gs, CX, compY + 110 + 38,
      `ε = 0.1 is typical; higher ε = more smoothing, less overconfidence`, C.gather.stroke);

    y = compY + 110 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Soft CE', 'Soft Cross-Entropy',
      `L_i = −Σ_j y_smooth[j] · log_p[i,j]`,
      `With soft targets, we compute the full dot product between y_smooth and log_p instead of gathering a single term. Since y_smooth[j≠target] = ε/V > 0, this adds a small penalty for assigning low probability to non-target classes, preventing the model from being overconfident in the target class.`,
      'step-dotprod', C.gather.stroke, C.gather.fill,
      [`# With soft targets`, `log_p = F.log_softmax(logits, dim=-1)`, `# element-wise multiply and sum`, `L_i = -(y_smooth * log_p).sum(dim=-1)`, `L = L_i.mean()`, `# PyTorch shortcut:`, `loss = F.cross_entropy(logits, targets, label_smoothing=0.1)`]));
  }

  // ── Step 5: Effect of Label Smoothing ────────────────────────────
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-effect', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Effect of Label Smoothing',
      `prevents overconfidence  →  better calibration & generalization`,
      C.smooth.fill, C.smooth.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Confidence comparison: standard vs smoothed
    const cols2 = [CX - 300, CX + 300];
    const titles = ['Without Smoothing', 'With Smoothing (ε=0.1)'];
    const probs = [
      [0.97, 0.01, 0.01, 0.01],
      [0.82, 0.06, 0.06, 0.06],
    ];

    for (let side = 0; side < 2; side++) {
      const cx2 = cols2[side];
      const c2 = side === 0 ? C.loss : C.softmax;
      lbl(gs, cx2, rowY - 20, titles[side], { size: 12, weight: '600', color: c2.stroke });

      const barW = 40, maxBarH = 100;
      const nBars = probs[side].length;
      for (let j = 0; j < nBars; j++) {
        const bx = cx2 - (nBars * barW) / 2 + j * barW + barW / 2;
        const bh = probs[side][j] * maxBarH;
        gs.append('rect').attr('x', bx - barW / 2 + 2).attr('y', rowY + maxBarH - bh)
          .attr('width', barW - 4).attr('height', bh)
          .attr('fill', c2.stroke).attr('opacity', j === 0 ? 0.7 : 0.3).attr('rx', 2);
        lbl(gs, bx, rowY + maxBarH + 14, `c${j}`, { size: 8, color: C.muted, font: 'monospace' });
        lbl(gs, bx, rowY + maxBarH - bh - 8,
          probs[side][j].toFixed(2),
          { size: 8, color: c2.stroke, font: 'monospace' });
      }
      lbl(gs, cx2, rowY + maxBarH + 30, `target class = c0`, { size: 9, color: C.muted, font: 'monospace' });
    }

    // Benefits list
    const benefitY = rowY + 160;
    const benefits = [
      { text: 'Calibration: predicted p closer to true accuracy', color: C.softmax.stroke },
      { text: 'Regularization: prevents fitting noise in labels', color: C.smooth.stroke },
      { text: 'Convergence: softer gradients on easy samples', color: C.gather.stroke },
    ];
    for (let i = 0; i < benefits.length; i++) {
      const bx = CX - 340 + i * 280;
      gs.append('rect').attr('x', bx - 110).attr('y', benefitY).attr('width', 220).attr('height', 60)
        .attr('rx', 6).attr('fill', '#fff').attr('stroke', benefits[i].color).attr('stroke-width', 1.5);
      const parts = benefits[i].text.split(': ');
      lbl(gs, bx, benefitY + 20, parts[0] + ':', { size: 10, weight: '600', color: benefits[i].color });
      lbl(gs, bx, benefitY + 40, parts[1], { size: 9, color: C.muted, font: 'monospace' });
    }

    shapeEq(gs, CX, benefitY + 90,
      `used in: Vision Transformers (ε=0.1), BERT-style pretraining, many modern classifiers`,
      C.smooth.stroke);
    sampleNote(gs, CX, benefitY + 90 + 38,
      `typical ε range: 0.05–0.2; ε=0 recovers standard cross-entropy`, C.smooth.stroke);

    y = benefitY + 90 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Effect', 'Effect of Label Smoothing',
      `ε ∈ [0, 1]: ε=0 → standard CE, ε→1 → uniform`,
      `Label smoothing is a regularization technique widely used in vision and NLP. With ε=0.1 (standard), it prevents the model from predicting probability 1.0 for the target class. Benefits: better calibration, reduced overfitting to noise in labels, slightly softer gradient signal on confident predictions.`,
      'step-effect', C.smooth.stroke, C.smooth.fill,
      [`# PyTorch label smoothing:`, `loss = F.cross_entropy(logits, targets, label_smoothing=0.1)`, `# Manually:`, `log_p = F.log_softmax(logits, dim=-1)`, `smooth_labels = torch.full_like(log_p, 0.1/V)`, `smooth_labels.scatter_(1, targets.unsqueeze(1), 1-0.1+0.1/V)`, `loss = -(smooth_labels * log_p).sum(dim=-1).mean()`]));
  }

  return { steps, y };
}

// ── Main entry point ─────────────────────────────────────────────────

export function renderCrossEntropyDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const B = Math.max(2, Math.min(Number(params.batch_size) || 32, 64));
  const V = Math.max(2, Math.min(Number(params.num_classes) || 1000, 100000));
  const variant = String(params.variant || 'standard') as CEVariant;

  const stepsMeta: CEStep[] = [];
  let y = 10;

  lbl(g, CX, y + 14, 'Cross-Entropy Loss', { size: 18, weight: '700', color: 'var(--text)' });
  lbl(g, CX, y + 36,
    variant === 'label_smoothing'
      ? 'Label Smoothing Cross-Entropy — soft targets prevent overconfidence'
      : 'Standard Cross-Entropy — maximum likelihood classification loss',
    { size: 11, color: C.muted });
  y += 56;

  const { steps, y: finalY } = variant === 'label_smoothing'
    ? renderLabelSmoothing(g, y, B, V)
    : renderStandard(g, y, B, V);
  stepsMeta.push(...steps);
  y = finalY;

  const insightText = variant === 'label_smoothing'
    ? `Label smoothing regularizes by replacing hard one-hot targets (y=1) with soft distributions (y_smooth = (1−ε)·one_hot + ε/V). This prevents overconfident predictions, improves calibration, and often improves generalization. Widely used in Vision Transformers, BERT, and modern classifiers with ε=0.1.`
    : `Cross-entropy H(p,q) = −Σ p(x)·log(q(x)) measures how well the model distribution q matches the true distribution p. For classification with one-hot labels, this simplifies to −log(q[target]). The gradient ∂L/∂z_j = p_j − 1[j=target] is elegant and efficient to compute.`;

  const perfText = `Cross-entropy is O(B × V) for the softmax and gather — effectively O(B × V) but with good hardware support. The gradient computation is numerically stable when using log_softmax + nll_loss rather than softmax + log + gather separately.`;

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'softmax', 'Softmax');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'backpropagation', 'Backpropagation');
  y += 80;

  const codeLines = variant === 'label_smoothing'
    ? [
      `import torch.nn.functional as F`, ``,
      `# Standard cross-entropy (for comparison)`,
      `loss = F.cross_entropy(logits, targets)`,
      ``,
      `# Label smoothing — PyTorch built-in`,
      `loss = F.cross_entropy(logits, targets, label_smoothing=0.1)`,
      ``,
      `# Manual implementation`,
      `eps = 0.1`,
      `log_p = F.log_softmax(logits, dim=-1)  # [B, V]`,
      `nll = -log_p.gather(-1, targets.unsqueeze(-1)).squeeze(-1)  # [B]`,
      `smooth_loss = -log_p.mean(dim=-1)  # [B]`,
      `loss = ((1 - eps) * nll + eps * smooth_loss).mean()`,
    ]
    : [
      `import torch.nn.functional as F`, ``,
      `# Standard cross-entropy`,
      `loss = F.cross_entropy(logits, targets)`,
      ``,
      `# Equivalent manual implementation`,
      `log_p = F.log_softmax(logits, dim=-1)    # [B, V]`,
      `nll = -log_p.gather(-1, targets.unsqueeze(-1))  # [B, 1]`,
      `loss = nll.mean()                         # scalar`,
      ``,
      `# Gradient ∂L/∂z_j = softmax(z)_j - 1[j == target]`,
    ];

  y = drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160,
    `Cross-Entropy Loss — ${variant === 'label_smoothing' ? 'Label Smoothing' : 'Standard'}`,
    [`variant: ${variant}`, `batch_size: ${B}`, `num_classes: ${V}`],
    codeLines);

  return { width: W, height: y + FOOTER_PAD, steps: stepsMeta };
}
